from math import cos, sin, radians

def walk(prog, start=(0.0, 0.0), h=90.0, pen=True):
    """Своя черепаха: список отрезков, нарисованных опущенным хвостом. prog — [('F', 10), ('R', 90), ('U', 0), ('D', 0), ...]."""
    x, y = start
    segs = []
    for c, v in prog:
        if c in 'FB':
            d = v if c == 'F' else -v
            nx, ny = round(x + d * cos(radians(h)), 9), round(y + d * sin(radians(h)), 9)
            if pen:
                segs.append(((x, y), (nx, ny)))
            x, y = nx, ny
        elif c == 'R':
            h -= v
        elif c == 'L':
            h += v
        elif c == 'U':
            pen = False
        elif c == 'D':
            pen = True
    return segs, (x, y), h

def polygon(segs):
    """Замкнутая фигура → вершины по порядку (первый обход, без повторов)."""
    pts = [segs[0][0]]
    for a, b in segs:
        pts.append(b)
        if b == pts[0]:
            break
    return pts[:-1]

def on_edge(px, py, poly):
    n = len(poly)
    for i in range(n):
        (x1, y1), (x2, y2) = poly[i], poly[(i + 1) % n]
        cross = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
        if abs(cross) < 1e-9 and min(x1, x2) - 1e-9 <= px <= max(x1, x2) + 1e-9 and min(y1, y2) - 1e-9 <= py <= max(y1, y2) + 1e-9:
            return True
    return False

def inside(px, py, poly):
    """Луч вправо: нечётное число пересечений — точка внутри."""
    res = False
    n = len(poly)
    for i in range(n):
        (x1, y1), (x2, y2) = poly[i], poly[(i + 1) % n]
        if (y1 > py) != (y2 > py):
            xc = x1 + (py - y1) * (x2 - x1) / (y2 - y1)
            if xc > px:
                res = not res
    return res

def count(poly, border=False):
    xs = [p[0] for p in poly]
    ys = [p[1] for p in poly]
    k = 0
    for x in range(int(min(xs)) - 1, int(max(xs)) + 2):
        for y in range(int(min(ys)) - 1, int(max(ys)) + 2):
            e = on_edge(x, y, poly)
            if (inside(x, y, poly) and not e) or (border and e):
                k += 1
    return k

